\set ON_ERROR_STOP on
SET ROLE hospital_owner;
SET search_path=pg_catalog,ext,public;
BEGIN;
CREATE TABLE inventory.supplier(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code text NOT NULL UNIQUE,name text NOT NULL,is_synthetic boolean NOT NULL DEFAULT true);
CREATE TABLE inventory.location(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,department_id bigint NOT NULL REFERENCES org.department,code text NOT NULL UNIQUE,name text NOT NULL);
CREATE TABLE inventory.item(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sku text NOT NULL UNIQUE,name text NOT NULL,medication_id integer UNIQUE REFERENCES ref.medication,unit_code text NOT NULL REFERENCES ref.unit,reorder_point numeric(18,4) NOT NULL CHECK(reorder_point>=0));
CREATE TABLE inventory.lot(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,item_id bigint NOT NULL REFERENCES inventory.item,lot_number text NOT NULL,expires_on date NOT NULL,supplier_id bigint NOT NULL REFERENCES inventory.supplier,received_on date NOT NULL,CHECK(expires_on>received_on),UNIQUE(item_id,lot_number),UNIQUE(id,item_id));
CREATE TABLE inventory.stock_balance(location_id bigint NOT NULL REFERENCES inventory.location,lot_id bigint NOT NULL REFERENCES inventory.lot,quantity numeric(18,4) NOT NULL DEFAULT 0 CHECK(quantity>=0),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(location_id,lot_id));
CREATE TABLE inventory.purchase_order(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_number text NOT NULL UNIQUE,supplier_id bigint NOT NULL REFERENCES inventory.supplier,status text NOT NULL CHECK(status IN('draft','approved','received','cancelled')),ordered_at timestamptz NOT NULL,currency_code char(3) NOT NULL REFERENCES ref.currency);
CREATE TABLE inventory.purchase_order_line(order_id bigint NOT NULL REFERENCES inventory.purchase_order,line_no integer NOT NULL CHECK(line_no>0),item_id bigint NOT NULL REFERENCES inventory.item,quantity ref.positive_quantity NOT NULL,unit_price ref.nonnegative_money NOT NULL,PRIMARY KEY(order_id,line_no));
CREATE TABLE pharmacy.medication_order(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint NOT NULL,medication_id integer NOT NULL REFERENCES ref.medication,ordered_by bigint NOT NULL REFERENCES org.staff,ordered_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('draft','active','completed','stopped','cancelled')),route_code text NOT NULL REFERENCES ref.route,instructions text NOT NULL,valid_during tstzrange NOT NULL CHECK(NOT isempty(valid_during)),UNIQUE(id,patient_id),UNIQUE(id,patient_id,medication_id),FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE pharmacy.dispense(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL,order_id bigint NOT NULL,medication_id integer NOT NULL,item_id bigint NOT NULL,lot_id bigint NOT NULL,location_id bigint NOT NULL REFERENCES inventory.location,quantity ref.positive_quantity NOT NULL,dispensed_at timestamptz NOT NULL,dispensed_by bigint NOT NULL REFERENCES org.staff,idempotency_key uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,UNIQUE(id,patient_id),FOREIGN KEY(order_id,patient_id,medication_id) REFERENCES pharmacy.medication_order(id,patient_id,medication_id),FOREIGN KEY(lot_id,item_id) REFERENCES inventory.lot(id,item_id));
CREATE TABLE pharmacy.administration(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL,order_id bigint NOT NULL,dispense_id bigint,administered_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('completed','not-done','entered-in-error')),quantity ref.positive_quantity,unit_code text REFERENCES ref.unit,performed_by bigint NOT NULL REFERENCES org.staff,note text,FOREIGN KEY(order_id,patient_id) REFERENCES pharmacy.medication_order(id,patient_id),FOREIGN KEY(dispense_id,patient_id) REFERENCES pharmacy.dispense(id,patient_id),CHECK(status<>'completed' OR (quantity IS NOT NULL AND unit_code IS NOT NULL)));
CREATE TABLE pharmacy.medication_reconciliation(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint NOT NULL,reconciled_at timestamptz NOT NULL,reconciled_by bigint NOT NULL REFERENCES org.staff,status text NOT NULL CHECK(status IN('in-progress','completed')),note text NOT NULL,FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE inventory.stock_movement(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,location_id bigint NOT NULL REFERENCES inventory.location,lot_id bigint NOT NULL REFERENCES inventory.lot,quantity_delta numeric(18,4) NOT NULL CHECK(quantity_delta<>0),movement_type text NOT NULL CHECK(movement_type IN('receipt','dispense','adjustment','transfer-in','transfer-out')),occurred_at timestamptz NOT NULL,recorded_by bigint NOT NULL REFERENCES org.staff,dispense_id bigint UNIQUE REFERENCES pharmacy.dispense,idempotency_key uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,reason ref.nonblank_text NOT NULL,CHECK((movement_type IN('receipt','transfer-in') AND quantity_delta>0) OR (movement_type IN('dispense','transfer-out') AND quantity_delta<0) OR movement_type='adjustment'),CHECK((movement_type='dispense')=(dispense_id IS NOT NULL)));
CREATE TABLE billing.payer(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code text NOT NULL UNIQUE,name text NOT NULL,kind text NOT NULL CHECK(kind IN('public','private','self-pay')));
CREATE TABLE billing.coverage(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,payer_id bigint NOT NULL REFERENCES billing.payer,policy_number text NOT NULL UNIQUE,valid_during daterange NOT NULL CHECK(NOT isempty(valid_during)),priority smallint NOT NULL CHECK(priority>0),UNIQUE(id,patient_id));
CREATE TABLE billing.tariff(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,service_id integer NOT NULL REFERENCES ref.service,payer_id bigint NOT NULL REFERENCES billing.payer,valid_during daterange NOT NULL CHECK(NOT isempty(valid_during)),amount ref.nonnegative_money NOT NULL,currency_code char(3) NOT NULL REFERENCES ref.currency,EXCLUDE USING gist(service_id WITH =,payer_id WITH =,valid_during WITH &&));
CREATE TABLE billing.invoice(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint NOT NULL,invoice_number text NOT NULL UNIQUE,payer_id bigint NOT NULL REFERENCES billing.payer,coverage_id bigint,issued_at timestamptz NOT NULL,due_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('draft','issued','void')),currency_code char(3) NOT NULL REFERENCES ref.currency,UNIQUE(id,patient_id),FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id),FOREIGN KEY(coverage_id,patient_id) REFERENCES billing.coverage(id,patient_id),CHECK(due_at>=issued_at));
CREATE TABLE billing.invoice_line(invoice_id bigint NOT NULL REFERENCES billing.invoice,line_no integer NOT NULL CHECK(line_no>0),service_id integer NOT NULL REFERENCES ref.service,quantity ref.positive_quantity NOT NULL,unit_price ref.nonnegative_money NOT NULL,discount_amount ref.nonnegative_money NOT NULL DEFAULT 0,tax_rate numeric(7,6) NOT NULL DEFAULT 0 CHECK(tax_rate BETWEEN 0 AND 1),net_amount numeric(18,2) GENERATED ALWAYS AS(round(quantity*unit_price-discount_amount,2)) STORED,tax_amount numeric(18,2) GENERATED ALWAYS AS(round((quantity*unit_price-discount_amount)*tax_rate,2)) STORED,PRIMARY KEY(invoice_id,line_no),CHECK(discount_amount<=quantity*unit_price));
CREATE TABLE billing.payment(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,payer_id bigint NOT NULL REFERENCES billing.payer,received_at timestamptz NOT NULL,amount ref.nonnegative_money NOT NULL CHECK(amount>0),currency_code char(3) NOT NULL REFERENCES ref.currency,method text NOT NULL CHECK(method IN('card','transfer','cash')),external_reference text NOT NULL UNIQUE,UNIQUE(id,patient_id));
CREATE TABLE billing.payment_allocation(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,payment_id bigint NOT NULL,invoice_id bigint NOT NULL,patient_id bigint NOT NULL,amount ref.nonnegative_money NOT NULL CHECK(amount>0),allocated_at timestamptz NOT NULL DEFAULT clock_timestamp(),FOREIGN KEY(payment_id,patient_id) REFERENCES billing.payment(id,patient_id),FOREIGN KEY(invoice_id,patient_id) REFERENCES billing.invoice(id,patient_id),UNIQUE(payment_id,invoice_id));
CREATE TABLE billing.claim(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL,invoice_id bigint NOT NULL UNIQUE,payer_id bigint NOT NULL REFERENCES billing.payer,claim_number text NOT NULL UNIQUE,status text NOT NULL CHECK(status IN('draft','submitted','accepted','rejected')),submitted_at timestamptz,adjudicated_at timestamptz,rejection_reason text,FOREIGN KEY(invoice_id,patient_id) REFERENCES billing.invoice(id,patient_id),CHECK(adjudicated_at IS NULL OR adjudicated_at>=submitted_at),CHECK(status<>'rejected' OR rejection_reason IS NOT NULL));
CREATE TABLE quality.incident(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint REFERENCES mpi.patient,encounter_id bigint,department_id bigint NOT NULL REFERENCES org.department,occurred_at timestamptz NOT NULL,reported_at timestamptz NOT NULL,reported_by bigint NOT NULL REFERENCES org.staff,category text NOT NULL,severity text NOT NULL CHECK(severity IN('near-miss','minor','moderate','severe')),status text NOT NULL CHECK(status IN('open','investigating','closed')),description text NOT NULL,CHECK(reported_at>=occurred_at),CHECK(encounter_id IS NULL OR patient_id IS NOT NULL),FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE quality.infection_case(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint NOT NULL,onset_at timestamptz NOT NULL,classification text NOT NULL CHECK(classification IN('suspected','confirmed','excluded')),organism_concept_id integer REFERENCES ref.concept,reported_by bigint NOT NULL REFERENCES org.staff,FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE quality.patient_feedback(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint NOT NULL,submitted_at timestamptz NOT NULL,rating smallint NOT NULL CHECK(rating BETWEEN 1 AND 5),comment_text text,FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE integration.outbox(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,aggregate_type text NOT NULL,aggregate_id text NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),published_at timestamptz,attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),next_attempt_at timestamptz NOT NULL DEFAULT clock_timestamp(),last_error text);
CREATE TABLE integration.inbox(source text NOT NULL,message_id text NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),payload_sha256 bytea NOT NULL CHECK(octet_length(payload_sha256)=32),status text NOT NULL CHECK(status IN('received','processed','failed')),processed_at timestamptz,error_text text,PRIMARY KEY(source,message_id));
CREATE TABLE integration.external_identifier(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,resource_type text NOT NULL CHECK(resource_type IN('Patient','Encounter','DiagnosticReport','MedicationRequest')),internal_public_id uuid NOT NULL,system_uri text NOT NULL,external_id text NOT NULL,UNIQUE(resource_type,system_uri,external_id),UNIQUE(resource_type,internal_public_id,system_uri));
CREATE TABLE integration.export_job(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,requested_by bigint NOT NULL REFERENCES iam.application_user,purpose text NOT NULL,requested_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('queued','running','completed','failed')),filter_json jsonb NOT NULL CHECK(jsonb_typeof(filter_json)='object'),output_uri text,completed_at timestamptz,CHECK(completed_at IS NULL OR completed_at>=requested_at));
CREATE TABLE audit.event(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),actor name NOT NULL,transaction_id bigint NOT NULL,table_schema name NOT NULL,table_name name NOT NULL,operation text NOT NULL CHECK(operation IN('INSERT','UPDATE','DELETE','BASELINE')),entity_key jsonb NOT NULL,changed_columns text[],request_id text,details jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE audit.access_event(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),actor name NOT NULL,patient_id bigint NOT NULL REFERENCES mpi.patient,purpose text NOT NULL,action text NOT NULL CHECK(action IN('read','export','break-glass')),request_id uuid NOT NULL,reason text NOT NULL);
INSERT INTO ops.schema_migration VALUES('03',clock_timestamp(),'Medication, stock ledger, revenue cycle, quality, integration and audit');
COMMIT;
